<script setup lang="ts">
import {formatBytes} from './format-bytes';
import {onMounted,onUnmounted,ref,watch} from 'vue';
import {vModal} from './modal';
const props=defineProps<{disabled:boolean}>(),emit=defineEmits<{authenticationRequired:[]}>();
type State={run_id:string;status:string;phase:string;worker_active:boolean;total_files:string;processed_files:string;total_bytes:string;processed_bytes:string;current_path:string;current_bytes:string;current_size:string;started_at_utc:string;updated_at_utc:string;retry_at_utc?:string|null;last_error:string};
const state=ref<State|null>(null),loading=ref(false),pending=ref(false),error=ref(''),message=ref(''),observed=ref(''),collapsed=ref(false),ack=ref(false),confirmation=ref<{run:string;method:'POST'|'DELETE'}|null>(null),estimate=ref<{files:string;bytes:string}|null>(null),estimating=ref(false);
const statuses:Record<string,string>={idle:'尚无扫描记录',running:'运行中',paused:'已暂停',failed:'失败',complete:'完成'};
const phases:Record<string,string>={idle:'未开始',restart_required:'检查点已作废，需重新扫描',hashing:'核对文件内容',backoff:'等待重试',paused:'已暂停',failed:'失败',complete:'完成'};
const exact=(x:unknown)=>typeof x==='string'&&/^(0|[1-9][0-9]*)$/.test(x)&&x.length<=19&&BigInt(x)<=9223372036854775807n;
const utc=(x:unknown)=>typeof x==='string'&&x.endsWith('Z')&&Number.isFinite(Date.parse(x));
let active=true,generation=0,controlGeneration=0,estimateGeneration=0,controller:AbortController|undefined,estimateController:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,consumed=false;
function stop(){controlGeneration++;if(pending.value){message.value='离页或会话失效时扫描请求尚未核对，结果未知；请先读取检查点，不会重发。';pending.value=false;confirmation.value=null;}active=false;generation++;estimateGeneration++;controller?.abort();estimateController?.abort();clearTimeout(timer);loading.value=false;estimating.value=false;}
function requireLogin(){stop();emit('authenticationRequired');}
async function load(){
 if(!active||props.disabled||loading.value)return;clearTimeout(timer);controller=new AbortController();const request=++generation;loading.value=true;
 try{const response=await fetch('/api/cloud-cleanup/duplicate-scan?identity_format=string',{credentials:'same-origin',signal:controller.signal});if(request!==generation)return;if(response.status===401){requireLogin();return;}if(!response.ok)throw Error(await response.text()||'扫描状态读取失败');const data=await response.json();if(request!==generation)return;
 if(!data||!Object.hasOwn(statuses,data.status)||!Object.hasOwn(phases,data.phase)||typeof data.worker_active!=='boolean'||typeof data.run_id!=='string'||(data.status!=='idle'&&!/^[a-f0-9]{32}$/.test(data.run_id))||!['total_files','processed_files','total_bytes','processed_bytes','current_bytes','current_size'].every(k=>exact(data[k]))||typeof data.current_path!=='string'||typeof data.last_error!=='string'||!utc(data.started_at_utc)||!utc(data.updated_at_utc)||(data.retry_at_utc!=null&&!utc(data.retry_at_utc)))throw Error('哈希扫描状态无效');
 state.value=data;observed.value=new Date().toISOString();error.value='';
 }catch(e:any){if(request===generation)error.value=e.message||'扫描状态暂不可读';}finally{if(request===generation){loading.value=false;if(active&&!props.disabled)timer=setTimeout(load,5000);}}
}
async function estimateCandidates(){
 if(!active||props.disabled||estimating.value||pending.value)return;estimating.value=true;estimateController=new AbortController();const request=++estimateGeneration;
 try{const response=await fetch('/api/cloud-cleanup/duplicate-scan?estimate=1&identity_format=string',{credentials:'same-origin',signal:estimateController.signal});if(request!==estimateGeneration)return;if(response.status===401){requireLogin();return;}if(!response.ok)throw Error(await response.text()||'候选预估失败');const data=await response.json();if(request!==estimateGeneration)return;if(!exact(data.files)||!exact(data.estimated_bytes))throw Error('候选预估无效');estimate.value={files:data.files,bytes:data.estimated_bytes};}
 catch(e:any){if(request===estimateGeneration)message.value=e.message||'候选预估失败';}finally{if(request===estimateGeneration)estimating.value=false;}
}
function prepare(method:'POST'|'DELETE'){if(!state.value||props.disabled||pending.value||loading.value||error.value)return;confirmation.value={run:state.value.run_id,method};ack.value=false;consumed=false;}
function close(){if(!pending.value)confirmation.value=null;}
async function submit(){
 const fixed=confirmation.value;if(!fixed||!active||props.disabled||pending.value||consumed||!ack.value)return;pending.value=true;consumed=true;const action=++controlGeneration;
 try{const response=await fetch('/api/cloud-cleanup/duplicate-scan'+(fixed.method==='DELETE'?'?expected_run_id='+fixed.run:''),{method:fixed.method,credentials:'same-origin',headers:{'Content-Type':'application/json'},...(fixed.method==='POST'?{body:JSON.stringify({expected_run_id:fixed.run})}:{})});if(!active||action!==controlGeneration)return;if(response.status===401){pending.value=false;confirmation.value=null;message.value='管理员登录失效，请重新登录核对。';requireLogin();return;}if(response.status>=500||response.status===408)throw Error('unknown');if(!response.ok){message.value='请求被拒绝：'+await response.text();return;}message.value=fixed.method==='POST'?'开始/恢复请求已接收，正在重新核对运行状态。':'暂停请求已接收，当前内容读取退出前可能仍在收尾。';}
 catch{if(active&&action===controlGeneration)message.value='请求结果未知，可能已执行；不会重发，请先核对重新读取的状态。';}
 finally{if(action===controlGeneration){pending.value=false;if(active){confirmation.value=null;generation++;controller?.abort();loading.value=false;load();}}}
}
function restore(event:PageTransitionEvent){if(event.persisted&&!props.disabled){active=true;load();}}
watch(()=>props.disabled,x=>{if(x)stop();});onMounted(()=>{window.addEventListener('pagehide',stop);window.addEventListener('pageshow',restore);load();});onUnmounted(()=>{stop();window.removeEventListener('pagehide',stop);window.removeEventListener('pageshow',restore);});
</script>
<!-- UI acceptance found inactive idle/completed states incorrectly suggested a prior restart. -->
<template><section class="event-results" data-testid="duplicate-scan-state"><header class="page-header"><h2>内容哈希扫描</h2><button class="button secondary" :disabled="disabled||loading" @click="load">刷新状态</button></header><p class="muted">扫描需要读取候选文件的真实内容以计算 SHA-256，可能耗时并占用网盘下载带宽。已有校验结果继续可供预览。</p><button class="button secondary" :disabled="disabled" @click="collapsed=!collapsed">{{collapsed?'展开进度':'收起进度'}}</button><p v-if="loading" role="status">正在读取检查点…</p><p v-if="error" role="alert" class="notice danger">{{error}}<span v-if="state"> · 下方保留上次读取结果。</span></p><p v-if="state">{{statuses[state.status]}} · {{phases[state.phase]}} · {{state.worker_active?'当前进程有执行器':state.status==='running'?'记录为运行中，但当前进程无执行器；请查看历史核对':'当前进程无执行器'}}</p><div v-show="!collapsed"><template v-if="state"><div class="event-table-scroll"><table><thead><tr><th>已校验 / 本轮候选</th><th>已读取 / 候选字节</th><th>当前文件读取</th></tr></thead><tbody><tr><td>{{state.processed_files}} / {{state.total_files}}</td><td>{{formatBytes(state.processed_bytes)}} / {{formatBytes(state.total_bytes)}}</td><td>{{formatBytes(state.current_bytes)}} / {{formatBytes(state.current_size)}}</td></tr></tbody></table></div><p v-if="state.current_path">当前文件：{{state.current_path}}</p><p v-if="state.retry_at_utc" class="notice">计划重试 UTC：{{state.retry_at_utc}}。等待期间不表示正在读取网盘。</p><p v-if="state.last_error" class="notice danger">{{state.last_error}}</p><p class="muted">运行 ID：{{state.run_id||'尚无'}}<template v-if="!state.updated_at_utc.startsWith('0001-')"><br>检查点更新 UTC：{{state.updated_at_utc}}</template></p><button class="button primary" data-testid="duplicate-start" :disabled="disabled||loading||pending||!!error" @click="prepare(state.worker_active?'DELETE':'POST')">{{state.worker_active?'暂停扫描':['idle','complete'].includes(state.status)?'开始扫描':'恢复扫描'}}</button></template><button class="button secondary" :disabled="disabled||estimating||pending" @click="estimateCandidates">{{estimating?'正在预估…':'预估剩余候选'}}</button><p v-if="estimate">本次本地预估：{{estimate.files}} 个文件 · {{formatBytes(estimate.bytes)}}。远端内容变化可能影响实际读取量。</p></div><p v-if="message" class="notice" role="status">{{message}}</p><p v-if="observed" class="muted">本机读取 UTC：{{observed}}</p><div v-if="confirmation" class="modal-backdrop"><section class="detail-drawer" role="dialog" aria-modal="true" aria-labelledby="duplicate-confirm-title" v-modal="close"><header class="page-header"><h2 id="duplicate-confirm-title">确认{{confirmation.method==='POST'?'开始或恢复':'暂停'}}哈希扫描</h2><button class="button secondary" :disabled="pending" @click="close">取消</button></header><p>绑定运行：{{confirmation.run||'尚无旧运行'}}</p><p>范围：全账号缓存中符合条件的内容候选。开始/恢复会读取文件内容，完整缓存和扫描互斥由服务端再核对。</p><label><input type="checkbox" v-model="ack" :disabled="pending"/>已核对运行与带宽影响</label><button class="button primary" data-testid="duplicate-confirm" :disabled="disabled||pending||!ack" @click="submit">{{pending?'正在提交…':'确认执行'}}</button></section></div></section></template>
